DROP MATERIALIZED VIEW "public"."v06a_edition_stats2";--> statement-breakpoint
CREATE MATERIALIZED VIEW "public"."v06a_edition_stats2" AS (select "round"."edition_id", count(distinct "team"."inst_id") as "total_institutes", count(distinct "task"."id") as "total_tasks" from "v02b_team_round_stats" inner join "team_round" on "team_round"."id" = "v02b_team_round_stats"."id" inner join "team" on ("team"."id" = "team_round"."team_id" and "team"."hidden" = false) inner join "task" on ("task"."round_id" = "team_round"."round_id" and "task"."regular" = true) inner join "round" on ("round"."id" = "team_round"."round_id" and "round"."public" = true) inner join "edition" on ("edition"."id" = "round"."edition_id" and "edition"."public" = true) where v02b_team_round_stats.championship = 'regolari' group by "round"."edition_id");